import type { Span } from '@opentelemetry/api';
import {
  EntityConflictError,
  HookNotFoundError,
  RunExpiredError,
  RuntimeDecryptionError,
} from '@workflow/errors';
import {
  type CreateEventParams,
  type CreateEventRequest,
  type EventResult,
  type SerializedData,
  SPEC_VERSION_CURRENT,
  type WorkflowRun,
  type World,
} from '@workflow/world';
import { importKey } from '../encryption.js';
import type {
  HookInvocationQueueItem,
  StepInvocationQueueItem,
  WaitInvocationQueueItem,
  WorkflowSuspension,
} from '../global.js';
import { runtimeLogger } from '../logger.js';
import { dehydrateStepArguments } from '../serialization.js';
import * as Attribute from '../telemetry/semantic-conventions.js';
import { serializeTraceCarrier } from '../telemetry.js';
import {
  type MutableEventLog,
  queueMessage,
  withPreconditionRetry,
} from './helpers.js';
import { unserializableStepInputPlaceholder } from './unserializable-step.js';

/**
 * Extracts W3C trace context headers from a trace carrier for HTTP propagation.
 * Returns an object with `traceparent` and optionally `tracestate` headers.
 */
function extractTraceHeaders(
  traceCarrier: Record<string, string>
): Record<string, string> {
  const headers: Record<string, string> = {};
  if (traceCarrier.traceparent) {
    headers.traceparent = traceCarrier.traceparent;
  }
  if (traceCarrier.tracestate) {
    headers.tracestate = traceCarrier.tracestate;
  }
  return headers;
}

export interface SuspensionHandlerParams {
  suspension: WorkflowSuspension;
  world: World;
  run: WorkflowRun;
  span?: Span;
  requestId?: string;
  /**
   * The runtime's loaded event log. Each event creation is sent with this
   * snapshot's `stateUpdatedAt` and, if the backend rejects it as stale (412),
   * the log is reloaded in place and the create is retried — see
   * `withPreconditionRetry`. Guarding per-create (rather than the whole
   * suspension) ensures a retry never re-issues an already-created event.
   */
  eventLog?: MutableEventLog;
}

export interface SuspensionHandlerResult {
  timeoutSeconds?: number;
  /**
   * Correlation IDs of steps whose arguments failed to serialize. Each was
   * finalized here as `step_created` (with a placeholder input — the real
   * input is precisely what refused to serialize) followed by `step_failed`
   * carrying the serialization error, so the next replay rejects the step's
   * promise and a try/catch around the step call observes the error —
   * exactly like a step-body failure. No step-execution message is
   * dispatched for these, so an immediate re-invocation is scheduled
   * (`timeoutSeconds: 0`): when the failed step was the only pending work,
   * nothing else would ever wake the run to observe the terminal event.
   */
  failedStepCorrelationIds?: Set<string>;
}

async function createHookEvent({
  runId,
  hookEvent,
  queueItem,
  requestId,
  createEvent,
}: {
  runId: string;
  hookEvent: CreateEventRequest;
  queueItem: HookInvocationQueueItem;
  requestId?: string;
  createEvent: (
    data: CreateEventRequest,
    params?: CreateEventParams
  ) => Promise<EventResult>;
}): Promise<{
  hasHookConflict: boolean;
  hasAwaitedHookCreation: boolean;
}> {
  try {
    const result = await createEvent(hookEvent, {
      requestId,
    });

    // Check if the world returned a hook_conflict event instead of hook_created.
    // The hook_conflict event is stored in the event log and will be replayed
    // on the next workflow invocation, causing the hook's promise to reject.
    if (result.event?.eventType === 'hook_conflict') {
      return {
        hasHookConflict: true,
        hasAwaitedHookCreation: false,
      };
    }

    return {
      hasHookConflict: false,
      hasAwaitedHookCreation: queueItem.hasConflictAwaiter === true,
    };
  } catch (err) {
    if (EntityConflictError.is(err)) {
      runtimeLogger.info('Hook already exists, continuing', {
        workflowRunId: runId,
        message: err.message,
      });
      return {
        hasHookConflict: false,
        hasAwaitedHookCreation: queueItem.hasConflictAwaiter === true,
      };
    }

    if (RunExpiredError.is(err)) {
      runtimeLogger.info('Workflow run already completed, skipping hook', {
        workflowRunId: runId,
        message: err.message,
      });
      return {
        hasHookConflict: false,
        hasAwaitedHookCreation: false,
      };
    }

    throw err;
  }
}

/**
 * Handles a workflow suspension by processing all pending operations (hooks, steps, waits).
 * Uses an event-sourced architecture where entities (steps, hooks) are created atomically
 * with their corresponding events via events.create().
 *
 * Processing order:
 * 1. Hooks are processed first to prevent race conditions with webhook receivers
 * 2. Steps and waits are processed in parallel after hooks complete
 */
export async function handleSuspension({
  suspension,
  world,
  run,
  span,
  requestId,
  eventLog,
}: SuspensionHandlerParams): Promise<SuspensionHandlerResult> {
  const runId = run.runId;
  const workflowName = run.workflowName;
  const workflowStartedAt = run.startedAt ? +run.startedAt : Date.now();

  // Create an event with the optimistic-concurrency guard when the caller
  // supplied a loaded event log; otherwise create it directly (callers without
  // a replay snapshot, e.g. tests). The guard reloads + retries on a stale
  // (412) rejection, keeping `eventLog` current in place. All suspension events
  // are non-run_created events on this run's `runId`.
  const createGuarded = (
    data: CreateEventRequest,
    params?: CreateEventParams
  ): Promise<EventResult> => {
    if (!eventLog) {
      return world.events.create(runId, data, params);
    }
    return withPreconditionRetry(runId, eventLog, (stateUpdatedAt) =>
      world.events.create(runId, data, { ...params, stateUpdatedAt })
    );
  };
  // Separate queue items by type
  const stepItems = suspension.steps.filter(
    (item): item is StepInvocationQueueItem => item.type === 'step'
  );
  const allHookItems = suspension.steps.filter(
    (item): item is HookInvocationQueueItem => item.type === 'hook'
  );
  const waitItems = suspension.steps.filter(
    (item): item is WaitInvocationQueueItem => item.type === 'wait'
  );

  // Split hooks by what actions they need
  const hooksNeedingCreation = allHookItems.filter(
    (item) => !item.hasCreatedEvent
  );
  // Hooks needing disposal: any disposed hook (including those needing creation first)
  // Hooks are created before disposal in the processing order below
  const hooksNeedingDisposal = allHookItems.filter((item) => item.disposed);

  // Resolve encryption key for this run
  const rawKey = await world.getEncryptionKeyForRun?.(run);
  const encryptionKey = rawKey ? await importKey(rawKey) : undefined;

  // Build hook_created events (World will atomically create hook entities)
  const hookEvents = await Promise.all(
    hooksNeedingCreation.map(async (queueItem) => {
      const hookMetadata: SerializedData | undefined =
        typeof queueItem.metadata === 'undefined'
          ? undefined
          : ((await dehydrateStepArguments(
              queueItem.metadata,
              runId,
              encryptionKey,
              suspension.globalThis
            )) as SerializedData);
      return {
        queueItem,
        hookEvent: {
          eventType: 'hook_created' as const,
          specVersion: SPEC_VERSION_CURRENT,
          correlationId: queueItem.correlationId,
          eventData: {
            token: queueItem.token,
            metadata: hookMetadata,
            isWebhook: queueItem.isWebhook ?? false,
          },
        },
      };
    })
  );

  // Process hooks first to prevent race conditions with webhook receivers
  // All hook creations run in parallel
  // Track any hook conflicts that occur - these will be handled by re-enqueueing the workflow
  let hasHookConflict = false;
  let hasAwaitedHookCreation = false;

  if (hookEvents.length > 0) {
    const results = await Promise.all(
      hookEvents.map(({ hookEvent, queueItem }) =>
        createHookEvent({
          runId,
          hookEvent,
          queueItem,
          requestId,
          createEvent: createGuarded,
        })
      )
    );
    hasHookConflict = results.some((result) => result.hasHookConflict);
    hasAwaitedHookCreation = results.some(
      (result) => result.hasAwaitedHookCreation
    );
  }

  // Process hook disposals - these release hook tokens for reuse by other workflows
  if (hooksNeedingDisposal.length > 0) {
    await Promise.all(
      hooksNeedingDisposal.map(async (queueItem) => {
        const hookDisposedEvent: CreateEventRequest = {
          eventType: 'hook_disposed' as const,
          specVersion: SPEC_VERSION_CURRENT,
          correlationId: queueItem.correlationId,
          eventData: {
            token: queueItem.token,
          },
        };
        try {
          await createGuarded(hookDisposedEvent, { requestId });
        } catch (err) {
          if (EntityConflictError.is(err)) {
            // Hook was already disposed by a concurrent invocation — safe to skip
            runtimeLogger.info(
              'Hook already disposed, skipping duplicate disposal',
              {
                workflowRunId: runId,
                correlationId: queueItem.correlationId,
                message: err.message,
              }
            );
          } else if (RunExpiredError.is(err)) {
            runtimeLogger.info(
              'Workflow run already completed, skipping hook disposal',
              {
                workflowRunId: runId,
                correlationId: queueItem.correlationId,
                message: err.message,
              }
            );
          } else if (HookNotFoundError.is(err)) {
            // Hook may have already been disposed or never created
            runtimeLogger.info('Hook not found for disposal, continuing', {
              workflowRunId: runId,
              correlationId: queueItem.correlationId,
              message: err.message,
            });
          } else {
            throw err;
          }
        }
      })
    );
  }

  // Build a map of stepId -> step event for steps that need creation
  const stepsNeedingCreation = new Set(
    stepItems
      .filter((queueItem) => !queueItem.hasCreatedEvent)
      .map((queueItem) => queueItem.correlationId)
  );

  // Correlation IDs of steps finalized as failed because their arguments
  // refused to serialize — see finalizeUnserializableStep below.
  const failedStepCorrelationIds = new Set<string>();

  /**
   * A step whose arguments fail to serialize is deterministic: every replay
   * re-derives the same unserializable value, so redelivering the
   * orchestrator message can never succeed. Instead of rejecting the whole
   * suspension (which fails the run from the outside, where no user code can
   * observe it), treat it exactly like a step-body failure: write
   * `step_created` with a placeholder input (every World requires the step
   * entity to exist before a terminal step event, and the real input is
   * precisely what refused to serialize) followed by `step_failed` carrying
   * the serialization error. The next replay rejects the step's promise with
   * it, so a try/catch around the step call observes the error; uncaught, it
   * propagates out of the workflow body and fails the run as a USER_ERROR —
   * without burning queue redeliveries either way.
   */
  const finalizeUnserializableStep = async (
    queueItem: StepInvocationQueueItem,
    error: Error
  ): Promise<void> => {
    runtimeLogger.warn(
      'Step arguments failed to serialize; failing the step so the ' +
        'workflow can observe the error',
      {
        workflowRunId: runId,
        correlationId: queueItem.correlationId,
        stepName: queueItem.stepName,
        error: error.message,
      }
    );
    // Marker placeholder (not empty args): byte-identical-to-zero-args would
    // make `workflow inspect steps` show "no arguments" for the one step
    // whose entire problem was its arguments.
    const placeholderInput = (await dehydrateStepArguments(
      unserializableStepInputPlaceholder(),
      runId,
      encryptionKey,
      suspension.globalThis
    )) as SerializedData;
    try {
      await createGuarded(
        {
          eventType: 'step_created' as const,
          specVersion: SPEC_VERSION_CURRENT,
          correlationId: queueItem.correlationId,
          eventData: {
            stepName: queueItem.stepName,
            workflowName: run.workflowName,
            input: placeholderInput,
          },
        },
        { requestId }
      );
    } catch (createErr) {
      if (EntityConflictError.is(createErr)) {
        // A concurrent handler already created the step — the failure is
        // deterministic, so it is racing toward the same step_failed below.
        runtimeLogger.info('Step already exists, continuing', {
          workflowRunId: runId,
          correlationId: queueItem.correlationId,
          message: createErr.message,
        });
      } else if (RunExpiredError.is(createErr)) {
        // Run already finished — nothing to observe the failure.
        return;
      } else {
        throw createErr;
      }
    }
    try {
      await createGuarded(
        {
          eventType: 'step_failed' as const,
          specVersion: SPEC_VERSION_CURRENT,
          correlationId: queueItem.correlationId,
          eventData: {
            stepName: queueItem.stepName,
            // The message carries the framed serialization hint; the step
            // consumer rejects the step's promise with a FatalError built
            // from it, exactly like any other step failure.
            error: error.message,
            stack: error.stack,
          },
        },
        { requestId }
      );
    } catch (failErr) {
      if (EntityConflictError.is(failErr) || RunExpiredError.is(failErr)) {
        // Step already terminal (a concurrent handler wrote the same
        // deterministic failure) or the run already finished.
        runtimeLogger.info(
          'Tried failing step, but step or run has already finished.',
          {
            workflowRunId: runId,
            correlationId: queueItem.correlationId,
            message: failErr.message,
          }
        );
      } else {
        throw failErr;
      }
    }
    failedStepCorrelationIds.add(queueItem.correlationId);
  };

  // Process steps and waits in parallel
  // Each step: create event (if needed) -> queue message
  // Each wait: create event (if needed)
  const ops: Promise<void>[] = [];

  // Steps: create event then queue message, all in parallel
  for (const queueItem of stepItems) {
    ops.push(
      (async () => {
        // Create step event if not already created
        if (stepsNeedingCreation.has(queueItem.correlationId)) {
          let dehydratedInput: Uint8Array | unknown;
          try {
            dehydratedInput = await dehydrateStepArguments(
              {
                args: queueItem.args,
                closureVars: queueItem.closureVars,
                thisVal: queueItem.thisVal,
              },
              runId,
              encryptionKey,
              suspension.globalThis
            );
          } catch (err) {
            if (RuntimeDecryptionError.is(err)) {
              // An SDK fault, not a user value problem. Keep its identity
              // (RUNTIME_ERROR) and current fail-the-suspension behavior.
              throw err;
            }
            // Every other failure out of dehydrateStepArguments is a
            // serialization failure on the step's own arguments.
            await finalizeUnserializableStep(
              queueItem,
              err instanceof Error ? err : new Error(String(err))
            );
            return;
          }
          const stepEvent: CreateEventRequest = {
            eventType: 'step_created' as const,
            specVersion: SPEC_VERSION_CURRENT,
            correlationId: queueItem.correlationId,
            eventData: {
              stepName: queueItem.stepName,
              workflowName: run.workflowName,
              input: dehydratedInput as SerializedData,
            },
          };
          try {
            await createGuarded(stepEvent, { requestId });
          } catch (err) {
            if (EntityConflictError.is(err)) {
              runtimeLogger.info('Step already exists, continuing', {
                workflowRunId: runId,
                correlationId: queueItem.correlationId,
                message: err.message,
              });
            } else {
              throw err;
            }
          }
        }

        // Queue step execution message
        // Serialize trace context once and include in both payload and headers
        // Payload: for manual context restoration in step handler
        // Headers: for automatic trace propagation by Vercel's infrastructure
        const traceCarrier = await serializeTraceCarrier();
        await queueMessage(
          world,
          `__wkf_step_${queueItem.stepName}`,
          {
            workflowName,
            workflowRunId: runId,
            workflowStartedAt,
            stepId: queueItem.correlationId,
            traceCarrier,
            requestedAt: new Date(),
          },
          {
            idempotencyKey: queueItem.correlationId,
            headers: {
              ...extractTraceHeaders(traceCarrier),
            },
          }
        );
      })()
    );
  }

  // Waits: create events in parallel (no queueing needed for waits)
  for (const queueItem of waitItems) {
    if (!queueItem.hasCreatedEvent) {
      ops.push(
        (async () => {
          const waitEvent: CreateEventRequest = {
            eventType: 'wait_created' as const,
            specVersion: SPEC_VERSION_CURRENT,
            correlationId: queueItem.correlationId,
            eventData: {
              resumeAt: queueItem.resumeAt,
            },
          };
          try {
            await createGuarded(waitEvent, { requestId });
          } catch (err) {
            if (EntityConflictError.is(err)) {
              runtimeLogger.info('Wait already exists, continuing', {
                workflowRunId: runId,
                correlationId: queueItem.correlationId,
                message: err.message,
              });
            } else {
              throw err;
            }
          }
        })()
      );
    }
  }

  // Await the step_created / wait_created event creates before returning.
  // The caller (workflowEntrypoint) only enqueues the step-dispatch queue
  // messages AFTER handleSuspension resolves, and the queue handler acks
  // the orchestrator message only after the caller resolves. So the step_created
  // events must be durable here, and the dispatch sends must complete in the caller,
  // all before ack. If the process crashes before this resolves, the orchestrator
  // message is not acked and VQS redelivers, re-creates the (idempotent)
  // step_created and re-dispatches, and recovers the run instead of orphaning it.
  await Promise.all(ops);

  // Calculate minimum timeout from waits
  const now = Date.now();
  const minTimeoutSeconds = waitItems.reduce<number | null>(
    (min, queueItem) => {
      const resumeAtMs = queueItem.resumeAt.getTime();
      const delayMs = Math.max(1000, resumeAtMs - now);
      const timeoutSeconds = Math.ceil(delayMs / 1000);
      if (min === null) return timeoutSeconds;
      return Math.min(min, timeoutSeconds);
    },
    null
  );

  span?.setAttributes({
    ...Attribute.WorkflowRunStatus('workflow_suspended'),
    ...Attribute.WorkflowStepsCreated(stepItems.length),
    ...Attribute.WorkflowHooksCreated(hooksNeedingCreation.length),
    ...Attribute.WorkflowWaitsCreated(waitItems.length),
    ...(failedStepCorrelationIds.size > 0
      ? Attribute.WorkflowStepsFailedSerialization(
          failedStepCorrelationIds.size
        )
      : {}),
  });

  // Steps whose arguments failed to serialize were finalized above as
  // step_created + step_failed (see finalizeUnserializableStep). No
  // step-execution message is dispatched for them, so when such a step is
  // the only pending work nothing would ever wake the run again — schedule
  // an immediate re-invocation. The replay rejects the step's promise with
  // the serialization error, which a try/catch around the step call
  // observes; uncaught, it propagates out of the workflow body and fails
  // the run as a USER_ERROR. Healthy sibling steps were already queued
  // above, so they execute in parallel invocations regardless.
  if (failedStepCorrelationIds.size > 0) {
    return { timeoutSeconds: 0, failedStepCorrelationIds };
  }

  // If any hook conflicts occurred, re-enqueue the workflow immediately
  // On the next iteration, the hook consumer will see the hook_conflict event
  // and reject the promise with a WorkflowRuntimeError
  // We do this after processing all other operations (steps, waits) to ensure
  // they are recorded in the event log before the re-execution
  if (hasHookConflict) {
    return { timeoutSeconds: 0 };
  }

  // A `hook.getConflict()` awaiter needs an immediate re-invocation: the
  // replay consumes the just-committed hook_created and resolves the
  // awaiter with `null`. Without it the run would sit idle until some
  // unrelated message woke it. Any pending steps were already queued
  // above, so they execute in parallel invocations regardless.
  if (hasAwaitedHookCreation) {
    return { timeoutSeconds: 0 };
  }

  if (minTimeoutSeconds !== null) {
    return { timeoutSeconds: minTimeoutSeconds };
  }

  return {};
}
